"""Read a disjoint audit group at the parent's captured EDB basis."""
import json,sys
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[3];sys.path.insert(0,str(R/'scripts'));from migrate_learner_history import connection
name=sys.argv[1];group=json.loads((H/(name+'.json')).read_text());D=H/name;D.mkdir(exist_ok=True);inv=json.loads((H/'inventory.json').read_text());basis=group['basis_t'];assert basis==inv['basis_t'];ids=set(group['topics']);topic_records=[t for t in inv['topics']if t[':db/id']in ids];links=[x for x in inv['links']if x[0]in ids];qids=sorted({q for t,k,q in links});db=connection()
pattern='[* {:question/difficulty [:db/id :db/ident]} {:question/answer-fields [* {:answer-field/type [:db/id :db/ident]} {:answer-field/choices [* {:answer/type [:db/id :db/ident]}]} {:answer-field/correct [:db/id]}]}]';questions=[]
for offset in range(0,len(qids),60):
 questions.extend(r[0]for r in db.query('[:find (pull ?q '+pattern+') :in $ [?q ...] :where [?q :question/id _]]',[qids[offset:offset+60]],D,'questions-'+str(offset),basis));print(name,'questions',len(questions),'/',len(qids),flush=True)
acts=[r[0]for r in db.query('[:find (pull ?a [* {:activity/steps [*]}]) :in $ [?t ...] :where [?a :activity/scope ?t] [?a :activity/type :activity.type/lesson]]',[sorted(ids)],D,'activities',basis)]
byactivity={a[':db/id']:a[':activity/scope'][':db/id']for a in acts};steps=[[byactivity[a[':db/id']],a[':db/id'],s[':db/id'],s[':step/content'][':db/id']]for a in acts for s in a.get(':activity/steps',[])if ':step/content'in s];cids=sorted({s[3]for s in steps});contents=[]
for offset in range(0,len(cids),60):contents.extend(r[0]for r in db.query('[:find (pull ?c [*]) :in $ [?c ...] :where [?c ?a ?v]]',[cids[offset:offset+60]],D,'contents-'+str(offset),basis))
kps=[k for t in topic_records for k in t[':topic/knowledge-points']];generators=[[k[':db/id'],k[':knowledge-point/question-generator']]for k in kps if ':knowledge-point/question-generator'in k];topics=[{'entity':t[':db/id'],'title':t[':topic/title'],'ma_id':t[':topic/math-academy-id'],'questions':sum(x[0]==t[':db/id']for x in links),'kp_ids':[k[':db/id']for k in t[':topic/knowledge-points']]}for t in topic_records];snap={'basis_t':basis,'topics':topics,'topic_records':topic_records,'knowledge_points':kps,'links':links,'questions':questions,'activities':acts,'steps':steps,'contents':contents,'generators':generators};assert len(questions)==len(qids);(D/'current.json').write_text(json.dumps(snap,default=str,indent=2)+'\n');print(name,'complete:',len(topics),'topics',len(questions),'questions',sum(':tutorial/content'in c for c in contents),'tutorials',len(generators),'registered generators',flush=True)
